import { unstable_cache } from 'next'
import { getPosts } from '@/lib/api'

const getCachedPosts = unstable_cache(
  async () => getPosts(),
  ['posts'],
  {
    revalidate: 3600, // 1 hour
    tags: ['posts'],
  },
)

export default async function Home() {
  const posts = await getCachedPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>by {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

